// IFR Trainer offline cache (generated by tools/build-pages.mjs)
const CACHE = 'ifr-trainer-8dc4e057ba';
const FILES = ["./","./index.html","./manifest.webmanifest","./icon-180.png","./icon-192.png","./icon-512.png"];
self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(FILES)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys().then((ks) => Promise.all(ks.filter((k) => k !== CACHE).map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});
// network first (new versions arrive when online), the saved copy when offline — and when the network is so slow
// that opening the app would just hang (a page load waits at most 4 s before the saved copy is used)
self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== location.origin) return;
  const saved = () => caches.match(req, { ignoreSearch: true }).then((r) => r || caches.match('./index.html'));
  // no-cache = always ask GitHub whether there's a newer copy (otherwise its 10-minute HTTP cache delays updates)
  const net = fetch(req, { cache: 'no-cache' }).then((res) => {
    if (res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(req, copy)); }
    return res;
  });
  const slow = new Promise((resolve) => setTimeout(() => saved().then((r) => { if (r) resolve(r); }), 4000));
  e.respondWith((req.mode === 'navigate' ? Promise.race([net, slow]) : net).catch(saved));
});
